(232498, 13824, 6855, '<td valign="top">I love the feel of this and the black and white finish.  Very nice!</td>', 'I love the feel of this and the black and white finish.  Very nice!', '2003-03-10 01:29:10.000000', NULL, 1),
(232500, 13528, 6817, '<td valign="top">Good eye.</td>', 'Good eye.', '2003-03-10 01:29:29.000000', NULL, 1),
