(232880, 13785, 6806, '<td valign="top">beautiful</td>', 'beautiful', '2003-03-10 10:06:31.000000', NULL, 1),
(232881, 13609, 6806, '<td valign="top">very good</td>', 'very good', '2003-03-10 10:07:18.000000', NULL, 1),
