INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(233638, 13561, 6999, '<td valign="top">I know cellists who''d murder you if you did that to their instrument! Great idea - execution gives 9/10 - I think the dynamic range is too great here, but only just. Highlights are flaring a little, no?</td>', 'I know cellists who''d murder you if you did that to their instrument! Great idea - execution gives 9/10 - I think the dynamic range is too great here, but only just. Highlights are flaring a little, no?', '2003-03-10 14:49:01.000000', NULL, 1),
(233639, 13764, 342, '<td valign="top">I gave you a high score, 8, but IMO, I would have liked this better without the people in the photo.</td>', 'I gave you a high score, 8, but IMO, I would have liked this better without the people in the photo.', '2003-03-10 14:49:03.000000', NULL, 1),
(233641, 13953, 6999, '<td valign="top">Thise trees to the right of frame could almost be out of a silver print - top marks for that. The woodwork on the building lets it down a little - too much light, I think, I get the sensation that you''re losong detail because of it, and certainly texture. And i feel that the composition calls for something darker at the foot of the frame. nit-picking though.</td>', 'Thise trees to the right of frame could almost be out of a silver print - top marks for that. The woodwork on the building lets it down a little - too much light, I think, I get the sensation that you''re losong detail because of it, and certainly texture. And i feel that the composition calls for something darker at the foot of the frame. nit-picking though.', '2003-03-10 14:52:09.000000', NULL, 1),
(233643, 13701, 342, '<td valign="top">IMO, this would have been a much better picture if tha pillar on the left had not gotten in the way.  You were not haging over the side when you took this, i hope</td>', 'IMO, this would have been a much better picture if tha pillar on the left had not gotten in the way.  You were not haging over the side when you took this, i hope', '2003-03-10 14:52:57.000000', NULL, 1),
(233645, 13801, 2000, '<td valign="top">It''s funny - this looks so natural in Sepia tones, it''s almost not noticable except for the water.  Very nice capture, angles, and framing.</td>', 'It''s funny - this looks so natural in Sepia tones, it''s almost not noticable except for the water.  Very nice capture, angles, and framing.', '2003-03-10 14:54:04.000000', NULL, 1),
(233646, 13636, 342, '<td valign="top">I think thjise is a better perspective and Lines pictures than a bridge picture.</td>', 'I think thjise is a better perspective and Lines pictures than a bridge picture.', '2003-03-10 14:54:40.000000', NULL, 1),
(233647, 13864, 6907, '<td valign="top">Very nice color composition.. the bg is crowded and hard to read the.</td>', 'Very nice color composition.. the bg is crowded and hard to read the.', '2003-03-10 14:54:52.000000', NULL, 1),
(233652, 13594, 6999, '<td valign="top">could almost be on a christmas card - great shot, but a little too orthodox for what I give top marks to. I guess a 9 won''t hurt though :-)</td>', 'could almost be on a christmas card - great shot, but a little too orthodox for what I give top marks to. I guess a 9 won''t hurt though :-)', '2003-03-10 14:58:23.000000', NULL, 1),
