(235251, 13543, 7160, '<td valign="top">I love this picture...the darkened sky creates a very surreal feeling. 10!</td>', 'I love this picture...the darkened sky creates a very surreal feeling. 10!', '2003-03-11 17:30:23.000000', NULL, 1),
(235254, 13911, 7033, '<td valign="top">Love the geometry and contrast of the bridge!</td>', 'Love the geometry and contrast of the bridge!', '2003-03-11 17:32:38.000000', NULL, 1),
