INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(235272, 13735, 4871, '<td valign="top">I don''t know if the purple does anything for me, but that''s just me!</td>', 'I don''t know if the purple does anything for me, but that''s just me!', '2003-03-11 17:41:47.000000', NULL, 1),
(235273, 13939, 4871, '<td valign="top">I like the ''rose amongst the thorns'' theme you have here. Was the sky colorised or is that a natural gradient?</td>', 'I like the ''rose amongst the thorns'' theme you have here. Was the sky colorised or is that a natural gradient?', '2003-03-11 17:42:43.000000', NULL, 1),
(235274, 13721, 7033, '<td valign="top">Great geometry in the bridge!  Seems a bit over-sharpened on my screen...</td>', 'Great geometry in the bridge!  Seems a bit over-sharpened on my screen...', '2003-03-11 17:42:47.000000', NULL, 1),
(235275, 13651, 7033, '<td valign="top">Nice... great feeling of motion.  Definitely tells a story.</td>', 'Nice... great feeling of motion.  Definitely tells a story.', '2003-03-11 17:44:38.000000', NULL, 1),
(235277, 13692, 7033, '<td valign="top">Nice shot!  Your frame really adds to the photo.</td>', 'Nice shot!  Your frame really adds to the photo.', '2003-03-11 17:46:24.000000', NULL, 1),
(235278, 13652, 7033, '<td valign="top">Great geometric patterns!</td>', 'Great geometric patterns!', '2003-03-11 17:48:19.000000', NULL, 1),
(235279, 13747, 7033, '<td valign="top">Great perspective!</td>', 'Great perspective!', '2003-03-11 17:49:34.000000', NULL, 1),
(235284, 13561, 4871, '<td valign="top">Now why didn''t I think of that! Fantastic idea! Nice use of lighting too.</td>', 'Now why didn''t I think of that! Fantastic idea! Nice use of lighting too.', '2003-03-11 17:51:57.000000', NULL, 1),
(235290, 13602, 1439, '<td valign="top">Ísland?</td>', 'Ísland?', '2003-03-11 18:08:56.000000', NULL, 1),
(235291, 13776, 7246, '<td valign="top">Maybe you could bridge the gap on how this applies?  I like the photo, but couldn''t get your meaning.</td>', 'Maybe you could bridge the gap on how this applies?  I like the photo, but couldn''t get your meaning.', '2003-03-11 18:11:26.000000', NULL, 1),
(235293, 13801, 7246, '<td valign="top">Great lines.</td>', 'Great lines.', '2003-03-11 18:12:50.000000', NULL, 1),
(235298, 13563, 7246, '<td valign="top">I would love if you had a little more focus on the bridge.</td>', 'I would love if you had a little more focus on the bridge.', '2003-03-11 18:20:23.000000', NULL, 1),
(235302, 13615, 7246, '<td valign="top">I wish this was just a little sharper.  Good shot.</td>', 'I wish this was just a little sharper.  Good shot.', '2003-03-11 18:28:34.000000', NULL, 1),
(235303, 13688, 7246, '<td valign="top">I wish you cropped this a little.  The color is great.</td>', 'I wish you cropped this a little.  The color is great.', '2003-03-11 18:31:45.000000', NULL, 1),
(235305, 13551, 7246, '<td valign="top">This is one of my favorites.  Great job.</td>', 'This is one of my favorites.  Great job.', '2003-03-11 18:33:22.000000', NULL, 1),
(235306, 13539, 7246, '<td valign="top">Nice perspective, but the woman is distracting.</td>', 'Nice perspective, but the woman is distracting.', '2003-03-11 18:35:26.000000', NULL, 1),
(235309, 13589, 4985, '<td valign="top">Beautiful colors! I love it.</td>', 'Beautiful colors! I love it.', '2003-03-11 18:43:59.000000', NULL, 1),
(235310, 13930, 4985, '<td valign="top">I really like this photo. So calm and cold.</td>', 'I really like this photo. So calm and cold.', '2003-03-11 18:45:29.000000', NULL, 1),
(235312, 13912, 4985, '<td valign="top">The warm colors are perfect (at least to me).  ;&gt;</td>', 'The warm colors are perfect (at least to me).  ;>', '2003-03-11 18:47:10.000000', NULL, 1),
(235313, 13740, 4985, '<td valign="top">Is that God I see up there? Really nice.</td>', 'Is that God I see up there? Really nice.', '2003-03-11 18:48:12.000000', NULL, 1),
(235314, 13547, 1005, '<td valign="top">Interesting concept.  Focus seems very sharp.  Lighting - not so good, there''s not enough contrast for displaying the "art" piece.  5 Swash</td>', 'Interesting concept.  Focus seems very sharp.  Lighting - not so good, there''s not enough contrast for displaying the "art" piece.  5 Swash', '2003-03-11 18:48:30.000000', NULL, 1),
(235316, 13768, 1005, '<td valign="top">Cute, nice color, but the focus seems slightly off.  5 Swash</td>', 'Cute, nice color, but the focus seems slightly off.  5 Swash', '2003-03-11 18:49:32.000000', NULL, 1),
(235317, 13608, 1647, '<td valign="top">Nice work - great composition and nice colour.  The image is perhaps a little bit blurry (perhaps camera shake) but in general well done.</td>', 'Nice work - great composition and nice colour.  The image is perhaps a little bit blurry (perhaps camera shake) but in general well done.', '2003-03-11 18:50:14.000000', NULL, 1),
(235319, 13595, 1005, '<td valign="top">That''s an old bridge!  Focus seems to be on the foreground (whereas the bridge is in the middle-ground).  Color seems pretty good.  (using the 1/3 rule?)  5 Swash</td>', 'That''s an old bridge!  Focus seems to be on the foreground (whereas the bridge is in the middle-ground).  Color seems pretty good.  (using the 1/3 rule?)  5 Swash', '2003-03-11 18:51:07.000000', NULL, 1),
(235320, 13681, 1005, '<td valign="top">Pretty sharp, but very dark.  5 Swash</td>', 'Pretty sharp, but very dark.  5 Swash', '2003-03-11 18:52:22.000000', NULL, 1),
(235322, 13776, 1005, '<td valign="top">Fun/interesting shot.  Is the bridge the web?  (I don''t see what I''d call an obvious bridge...)  That''s a plastic spider, right?  Focus on the woman is very sharp.  The faked webbing - on the left it works pretty good, but on the right...honestly, it looks more like hair or part of a horse''s mane.  5 Swash</td>', 'Fun/interesting shot.  Is the bridge the web?  (I don''t see what I''d call an obvious bridge...)  That''s a plastic spider, right?  Focus on the woman is very sharp.  The faked webbing - on the left it works pretty good, but on the right...honestly, it looks more like hair or part of a horse''s mane.  5 Swash', '2003-03-11 18:56:41.000000', NULL, 1),
(235323, 13543, 1005, '<td valign="top">Very cool!  Possible winner here!  Sharp as a tack!  Very nice contrasts.  The closest thing to a nit is the grain in the sky, but honestly, that could be passed off as clouds.  Score upgrade from 9 to 10!  Swash</td>', 'Very cool!  Possible winner here!  Sharp as a tack!  Very nice contrasts.  The closest thing to a nit is the grain in the sky, but honestly, that could be passed off as clouds.  Score upgrade from 9 to 10!  Swash', '2003-03-11 18:57:59.000000', NULL, 1),
(235324, 13662, 4985, '<td valign="top">Wow!</td>', 'Wow!', '2003-03-11 18:58:17.000000', NULL, 1),
(235326, 13564, 1005, '<td valign="top">Very cool use of fisheye lens!  The vigenetting at the corners is totally justifiable with this lens (I hope you aren''t getting too many foolish comments on that!)  Very nice job!  9 Swash</td>', 'Very cool use of fisheye lens!  The vigenetting at the corners is totally justifiable with this lens (I hope you aren''t getting too many foolish comments on that!)  Very nice job!  9 Swash', '2003-03-11 18:59:35.000000', NULL, 1),
(235327, 13975, 1005, '<td valign="top">Very cool picture.  You might have saturated the green a tad heavily (see the cattails?), but I do that often myself.  Very cool reflection.  Very peaceful scene.  Focus seems very nice.  Not a spectacular bridge, but I like it!  9 Swash</td>', 'Very cool picture.  You might have saturated the green a tad heavily (see the cattails?), but I do that often myself.  Very cool reflection.  Very peaceful scene.  Focus seems very nice.  Not a spectacular bridge, but I like it!  9 Swash', '2003-03-11 19:01:39.000000', NULL, 1),
(235329, 13659, 1005, '<td valign="top">Very pretty picture.  It''s a cool bridge (looks like a living bridge, except for the whiteness of the limbs).  I esp. like the center 1/3 of this shot.  The bridge and the pond beyond it are very cool!  The "stream" and far bank..I could live without.  Very sharp photo, color might be a tad muted.  8 Swash</td>', 'Very pretty picture.  It''s a cool bridge (looks like a living bridge, except for the whiteness of the limbs).  I esp. like the center 1/3 of this shot.  The bridge and the pond beyond it are very cool!  The "stream" and far bank..I could live without.  Very sharp photo, color might be a tad muted.  8 Swash', '2003-03-11 19:04:42.000000', NULL, 1),
(235331, 13903, 4985, '<td valign="top">I just really like this. It leaves alot to the imagination.</td>', 'I just really like this. It leaves alot to the imagination.', '2003-03-11 19:05:11.000000', NULL, 1),
(235336, 13978, 5822, '<td valign="top">I''m not crazy about the composition cause I find there''s just too much going on here. I would have preferred that you cut out the bottom third of the picture and concentrate on the main subject.</td>', 'I''m not crazy about the composition cause I find there''s just too much going on here. I would have preferred that you cut out the bottom third of the picture and concentrate on the main subject.', '2003-03-11 19:14:22.000000', NULL, 1),
(235337, 13794, 4985, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2003-03-11 19:14:38.000000', NULL, 1),
(235338, 13977, 5822, '<td valign="top">I love the angle here and the way it shows off the curves of the bridge. Well done.</td>', 'I love the angle here and the way it shows off the curves of the bridge. Well done.', '2003-03-11 19:15:30.000000', NULL, 1),
(235340, 13846, 6520, '<td valign="top">great spot.I am not crazy about the picture clarity</td>', 'great spot.I am not crazy about the picture clarity', '2003-03-11 19:16:08.000000', NULL, 1),
(235341, 13531, 5822, '<td valign="top">Great DOF and very well focused, but I find the picture to be just a little flat that could have been improved with better contrast</td>', 'Great DOF and very well focused, but I find the picture to be just a little flat that could have been improved with better contrast', '2003-03-11 19:17:22.000000', NULL, 1),
(235345, 13735, 5822, '<td valign="top">I like the idea here for what you did with the color, just wish it  had been done a little more subtley. In addition, focusing could have been better. What are those black blotches near the border?</td>', 'I like the idea here for what you did with the color, just wish it  had been done a little more subtley. In addition, focusing could have been better. What are those black blotches near the border?', '2003-03-11 19:20:50.000000', NULL, 1),
(235346, 13787, 1005, '<td valign="top">Very sharp photo!  Color seems very good.  Your title is a little difficult (but I think I eventually figured it out).  The tree sticking out of the top of the sign might have been cool, but need more of it and maybe not quite so much coming out of the sign.  Sorry, but the photo doesn''t grab me, even with the political slam.  5 Swash</td>', 'Very sharp photo!  Color seems very good.  Your title is a little difficult (but I think I eventually figured it out).  The tree sticking out of the top of the sign might have been cool, but need more of it and maybe not quite so much coming out of the sign.  Sorry, but the photo doesn''t grab me, even with the political slam.  5 Swash', '2003-03-11 19:22:44.000000', NULL, 1),
(235347, 13718, 5822, '<td valign="top">Sharpened a bitt too much, I think. Also, this may be a nit pick, but it appears the picture could have been rotated ever so slightly CCW by maybe a degree.</td>', 'Sharpened a bitt too much, I think. Also, this may be a nit pick, but it appears the picture could have been rotated ever so slightly CCW by maybe a degree.', '2003-03-11 19:23:13.000000', NULL, 1),
(235349, 13818, 2011, '<td valign="top">I think this would do very well in black and white also.  Did you try it?</td>', 'I think this would do very well in black and white also.  Did you try it?', '2003-03-11 19:25:45.000000', NULL, 1),
(235350, 13911, 6110, '<td valign="top">nice use of patterns and shadows.</td>', 'nice use of patterns and shadows.', '2003-03-11 19:26:03.000000', NULL, 1),
(235352, 13756, 5822, '<td valign="top">While the bridge itself is nothing special, the rest of the picture is and has a great wilderness feel to it, which I love.  It appears a bit underexposed. Also, I wish the hanging tree branch in the upper left hand corner was out of the way.</td>', 'While the bridge itself is nothing special, the rest of the picture is and has a great wilderness feel to it, which I love.  It appears a bit underexposed. Also, I wish the hanging tree branch in the upper left hand corner was out of the way.', '2003-03-11 19:27:12.000000', NULL, 1),
(235353, 13683, 6110, '<td valign="top">like the sense of motion, wish it wasn''t so bright esp on the right side.</td>', 'like the sense of motion, wish it wasn''t so bright esp on the right side.', '2003-03-11 19:27:31.000000', NULL, 1),
(235355, 13619, 2011, '<td valign="top">Cool shot with the plane.</td>', 'Cool shot with the plane.', '2003-03-11 19:27:37.000000', NULL, 1),
(235356, 13673, 1005, '<td valign="top">While I do like the bare trees, it seems incongreous (sp) with the bridge and far background.  You might want to revisit your frame again, too.  The white to white edges just don''t work well for me.  5 Swash</td>', 'While I do like the bare trees, it seems incongreous (sp) with the bridge and far background.  You might want to revisit your frame again, too.  The white to white edges just don''t work well for me.  5 Swash', '2003-03-11 19:27:45.000000', NULL, 1),
(235358, 13831, 6110, '<td valign="top">beauty!</td>', 'beauty!', '2003-03-11 19:28:03.000000', NULL, 1),
(235359, 13535, 6520, '<td valign="top">very nice!</td>', 'very nice!', '2003-03-11 19:28:25.000000', NULL, 1),
(235360, 13697, 1005, '<td valign="top">Nice contrast between the two bridges.  Challenge well met (two for the price of one!!)  Color seems pretty good.  Focus - the cement bridge seems to look much better than the steel one.  5 Swash</td>', 'Nice contrast between the two bridges.  Challenge well met (two for the price of one!!)  Color seems pretty good.  Focus - the cement bridge seems to look much better than the steel one.  5 Swash', '2003-03-11 19:29:18.000000', NULL, 1),
(235361, 13755, 5822, '<td valign="top">Very good perspective and DOF and I also like the way you captured the reflection of the bridge in the water. Also, it''s a bit overexposed and I find that the highlights appear to lack detail.</td>', 'Very good perspective and DOF and I also like the way you captured the reflection of the bridge in the water. Also, it''s a bit overexposed and I find that the highlights appear to lack detail.', '2003-03-11 19:29:53.000000', NULL, 1),
(235362, 13716, 2000, '<td valign="top">I like the theme and subject matter - the photograph itself, however, is really too dark/red for my liking.  The lighting actually seems to eliminate a good portion of both bridge spans as well, though if the picture were a bit better lit, that effect might look good.</td>', 'I like the theme and subject matter - the photograph itself, however, is really too dark/red for my liking.  The lighting actually seems to eliminate a good portion of both bridge spans as well, though if the picture were a bit better lit, that effect might look good.', '2003-03-11 19:30:00.000000', NULL, 1),
(235363, 13882, 1717, '<td valign="top">lovely photo...looks very serene there.  well done!</td>', 'lovely photo...looks very serene there.  well done!', '2003-03-11 19:30:29.000000', NULL, 1),
(235364, 13974, 2011, '<td valign="top">This is awesome.. has a really dream like quality to it. 10</td>', 'This is awesome.. has a really dream like quality to it. 10', '2003-03-11 19:30:46.000000', NULL, 1),
(235365, 13842, 1005, '<td valign="top">Sharp photo.  Good color, too.  Something about the rail just doesn''t look quite right to me.  Sorry, but I don''t find a lot of interest (maybe the graffitti....)   5 Swash</td>', 'Sharp photo.  Good color, too.  Something about the rail just doesn''t look quite right to me.  Sorry, but I don''t find a lot of interest (maybe the graffitti....)   5 Swash', '2003-03-11 19:31:33.000000', NULL, 1),
(235369, 13755, 6110, '<td valign="top">nice composition, b&amp;w works well</td>', 'nice composition, b&w works well', '2003-03-11 19:33:01.000000', NULL, 1),
(235371, 13639, 5822, '<td valign="top">I don''t know if you did this on purpose, but I like the surreal effect you got with the over exposed background and also the duotones of this shot. The silouette of the person under the bridge is really neat, but I also wish you had cropped out the power lines tower and also waited to get another shot of the bridge without any moving traffic.</td>', 'I don''t know if you did this on purpose, but I like the surreal effect you got with the over exposed background and also the duotones of this shot. The silouette of the person under the bridge is really neat, but I also wish you had cropped out the power lines tower and also waited to get another shot of the bridge without any moving traffic.', '2003-03-11 19:34:42.000000', NULL, 1),
(235372, 13917, 5822, '<td valign="top">Neat perspective</td>', 'Neat perspective', '2003-03-11 19:35:20.000000', NULL, 1),
(235373, 13636, 2000, '<td valign="top">And what a perspective it is - the lighting makes the far side of the river look somewhat spooky.  I like the composition and content as well.</td>', 'And what a perspective it is - the lighting makes the far side of the river look somewhat spooky.  I like the composition and content as well.', '2003-03-11 19:35:35.000000', NULL, 1),
(235377, 13584, 5822, '<td valign="top">Not sure if that''s fog in the background from a warm day or picture was over exposed. I believe the former. Wish you had cropped out the cars at the bottom.</td>', 'Not sure if that''s fog in the background from a warm day or picture was over exposed. I believe the former. Wish you had cropped out the cars at the bottom.', '2003-03-11 19:37:10.000000', NULL, 1),
(235378, 13872, 2000, '<td valign="top">I think you over-sepiaed this picture - there''s too much bleach white space that I don''t think would have been present in the original photo.  Otherwise, nice photograph of this foot-bridge.</td>', 'I think you over-sepiaed this picture - there''s too much bleach white space that I don''t think would have been present in the original photo.  Otherwise, nice photograph of this foot-bridge.', '2003-03-11 19:39:32.000000', NULL, 1),
(235379, 13621, 5822, '<td valign="top">I like the color scheme here very much, even if you had to over expose to get the lights so vivid. Did you use a star filter here? Also, the green of the right side of the bridge really goes well with the other colors in the picture. Just to balance out the picture, since you don'' t have alot going on in the top half, I would have moved the horizon line up midway.</td>', 'I like the color scheme here very much, even if you had to over expose to get the lights so vivid. Did you use a star filter here? Also, the green of the right side of the bridge really goes well with the other colors in the picture. Just to balance out the picture, since you don'' t have alot going on in the top half, I would have moved the horizon line up midway.', '2003-03-11 19:40:19.000000', NULL, 1),
(235381, 13814, 5822, '<td valign="top">I like the lines and the graffiti on the walls makes for a very interesting photo, but I just wish they graffiti was brought out a little more with better saturation. Also, think the picture would work better with the bottom cropped out so that it showed no beach.</td>', 'I like the lines and the graffiti on the walls makes for a very interesting photo, but I just wish they graffiti was brought out a little more with better saturation. Also, think the picture would work better with the bottom cropped out so that it showed no beach.', '2003-03-11 19:42:58.000000', NULL, 1),
(235382, 13787, 2011, '<td valign="top">ironic</td>', 'ironic', '2003-03-11 19:43:17.000000', NULL, 1),
(235385, 13953, 5822, '<td valign="top">I''m not sure where the bridge is here, but I like very much the duotones of this picture. Also, think it could be improved by cropping out most of the sky. I like the angle of the shot very much and the DOF is very good.</td>', 'I''m not sure where the bridge is here, but I like very much the duotones of this picture. Also, think it could be improved by cropping out most of the sky. I like the angle of the shot very much and the DOF is very good.', '2003-03-11 19:45:50.000000', NULL, 1),
(235386, 13864, 6505, '<td valign="top">The clutter in the front is distracting to an otherwise nice picture.  A shot in front of all that would have been great.</td>', 'The clutter in the front is distracting to an otherwise nice picture.  A shot in front of all that would have been great.', '2003-03-11 19:45:59.000000', NULL, 1),
(235390, 13554, 3976, '<td valign="top">where is this at?</td>', 'where is this at?', '2003-03-11 19:50:53.000000', NULL, 1),
(235391, 13903, 1647, '<td valign="top">Nice work - almost a fraction too much fog, but what an interesting shot.  Great focus as well.</td>', 'Nice work - almost a fraction too much fog, but what an interesting shot.  Great focus as well.', '2003-03-11 19:50:58.000000', NULL, 1),
(235394, 13971, 1647, '<td valign="top">This image seems a little too dark in general.  Also the small pieces of red are lost in the image (they are too small and almost appear as defects at first).  I do like your composition of the bridge though.</td>', 'This image seems a little too dark in general.  Also the small pieces of red are lost in the image (they are too small and almost appear as defects at first).  I do like your composition of the bridge though.', '2003-03-11 19:52:03.000000', NULL, 1),
(235395, 13844, 6328, '<td valign="top">Really cute bridge in the park setting.  doesn''t look like it gets much use. Nice shadows from the tree, and lovely blue sky too.</td>', 'Really cute bridge in the park setting.  doesn''t look like it gets much use. Nice shadows from the tree, and lovely blue sky too.', '2003-03-11 19:52:06.000000', NULL, 1),
(235396, 13663, 5622, '<td valign="top">Original. I am fairly fond of this.</td>', 'Original. I am fairly fond of this.', '2003-03-11 19:52:39.000000', NULL, 1),
(235397, 13804, 1647, '<td valign="top">I like the sepia tones, and the fact that the image is darkest around the edges.  I also like the panorama aspect ratio</td>', 'I like the sepia tones, and the fact that the image is darkest around the edges.  I also like the panorama aspect ratio', '2003-03-11 19:52:47.000000', NULL, 1),
(235398, 13562, 3976, '<td valign="top">the interlaced art of the bridges is dope, to bad you didn''t have any sky for the top right corner.</td>', 'the interlaced art of the bridges is dope, to bad you didn''t have any sky for the top right corner.', '2003-03-11 19:53:00.000000', NULL, 1),
(235401, 13861, 1647, '<td valign="top">Good focus and colour.  It''s cropped a bit too close on the right edge for my liking (I''d like about 1cm beside the rig).</td>', 'Good focus and colour.  It''s cropped a bit too close on the right edge for my liking (I''d like about 1cm beside the rig).', '2003-03-11 19:54:15.000000', NULL, 1),
(235402, 13538, 6505, '<td valign="top">Dude, you messed up the border!  Ah, what a great shot though.  The border doesn''t mess it up too bad.</td>', 'Dude, you messed up the border!  Ah, what a great shot though.  The border doesn''t mess it up too bad.', '2003-03-11 19:54:22.000000', NULL, 1),
(235403, 13948, 6328, '<td valign="top">Personally, would like to see much more of this bridge, it seems so lovely, it''s too bad you didn''t use a wider angle on your lens.  The stone formation on the pier sure looks nice, but you don''t give the looker much else to comment on. . .</td>', 'Personally, would like to see much more of this bridge, it seems so lovely, it''s too bad you didn''t use a wider angle on your lens.  The stone formation on the pier sure looks nice, but you don''t give the looker much else to comment on. . .', '2003-03-11 19:54:30.000000', NULL, 1),
(235404, 13674, 1647, '<td valign="top">Great colour and lighting.  I really like this shot.</td>', 'Great colour and lighting.  I really like this shot.', '2003-03-11 19:55:08.000000', NULL, 1),
(235405, 13738, 5822, '<td valign="top">Think you under exposed the shot a little, but I lik he colors and the perspective. Also, it''s not clear to me that this is in fact a bridge except for the very hard to see clue in the upper right hand corner that it does go over what appears to me to be water.</td>', 'Think you under exposed the shot a little, but I lik he colors and the perspective. Also, it''s not clear to me that this is in fact a bridge except for the very hard to see clue in the upper right hand corner that it does go over what appears to me to be water.', '2003-03-11 19:55:10.000000', NULL, 1),
(235407, 13892, 6328, '<td valign="top">you''ve got the makings of a nice photo here, but I would sure like to have seen more of the bridge from a wider perspective, say a few hundred feet away at least.  Nice colors, nice and crisp focus, you can sure see the strength of the concrete and the steel that it shows.</td>', 'you''ve got the makings of a nice photo here, but I would sure like to have seen more of the bridge from a wider perspective, say a few hundred feet away at least.  Nice colors, nice and crisp focus, you can sure see the strength of the concrete and the steel that it shows.', '2003-03-11 19:56:45.000000', NULL, 1),
(235408, 13800, 1647, '<td valign="top">Something seems strange about this image.  Is it a double exposure or something?  I don''t think it is but something about the cables from the centre pilon looks odd.</td>', 'Something seems strange about this image.  Is it a double exposure or something?  I don''t think it is but something about the cables from the centre pilon looks odd.', '2003-03-11 19:56:52.000000', NULL, 1),
(235409, 13648, 2373, '<td valign="top">I really like this but i think the foreground being out of focus is distracting. My attention is drawn toward the unfocused part rather than the focused. 7,  Kevin</td>', 'I really like this but i think the foreground being out of focus is distracting. My attention is drawn toward the unfocused part rather than the focused. 7,  Kevin', '2003-03-11 19:57:35.000000', NULL, 1),
(235410, 13818, 5622, '<td valign="top">love the slow shutter speed great shot</td>', 'love the slow shutter speed great shot', '2003-03-11 19:58:31.000000', NULL, 1),
(235411, 13738, 2000, '<td valign="top">If you can, I''d like to suggest saving the photo with a slightly higher quality - DPC allows 150k, and this photo is ~75k (about 1/2).  The photo is somewhat grainy, especially noticable in the sky.  Nice shot, however... this appears to be looking into DC?</td>', 'If you can, I''d like to suggest saving the photo with a slightly higher quality - DPC allows 150k, and this photo is ~75k (about 1/2).  The photo is somewhat grainy, especially noticable in the sky.  Nice shot, however... this appears to be looking into DC?', '2003-03-11 19:59:02.000000', NULL, 1),
(235412, 13753, 5822, '<td valign="top">This is certainly a very unusual view of the bridge, which I''m not sure I like...it''s making me dizzy!  I know you probably did it cause you didn''t want to have the same kind of shot that most others had.  I think it would have worked on it''s own without the severe angle because you did a nice job on the color of the bridge and sky, as well as, the way you captured the massiveness of the structure.</td>', 'This is certainly a very unusual view of the bridge, which I''m not sure I like...it''s making me dizzy!  I know you probably did it cause you didn''t want to have the same kind of shot that most others had.  I think it would have worked on it''s own without the severe angle because you did a nice job on the color of the bridge and sky, as well as, the way you captured the massiveness of the structure.', '2003-03-11 19:59:31.000000', NULL, 1),
(235413, 13878, 6328, '<td valign="top">You''ve given me a "Wow" here, my friend!  Nice job, indeed.  I especially like the reflections in the water that you''ve captured.  you''ve got nice tones, nice DOF, I like the way the bridge just fades away off into the distance, it''s so long. . .  Is that real fog - or did you create it?  A really beautiful photograph!</td>', 'You''ve given me a "Wow" here, my friend!  Nice job, indeed.  I especially like the reflections in the water that you''ve captured.  you''ve got nice tones, nice DOF, I like the way the bridge just fades away off into the distance, it''s so long. . .  Is that real fog - or did you create it?  A really beautiful photograph!', '2003-03-11 20:00:08.000000', NULL, 1),
(235415, 13788, 5822, '<td valign="top">I find the graffiti a bit distracting and don''t like the dark area in the bottom left</td>', 'I find the graffiti a bit distracting and don''t like the dark area in the bottom left', '2003-03-11 20:02:39.000000', NULL, 1),
(235416, 13536, 6999, '<td valign="top">Great, great shot. absolutely no criticisms whatsoever, or even suggestions. top so far</td>', 'Great, great shot. absolutely no criticisms whatsoever, or even suggestions. top so far', '2003-03-11 20:03:06.000000', NULL, 1),
(235417, 13538, 6328, '<td valign="top">Hey - nice photo, but it''s kinda small.  You should make sure it''s moved up to 150 k next time, make it easier for us to see. Nice scenery with the mountain in the background, but can''t really see much detail to say much more.  sorry.</td>', 'Hey - nice photo, but it''s kinda small.  You should make sure it''s moved up to 150 k next time, make it easier for us to see. Nice scenery with the mountain in the background, but can''t really see much detail to say much more.  sorry.', '2003-03-11 20:03:16.000000', NULL, 1),
(235418, 13681, 5822, '<td valign="top">Appears way too underexposed, but I like the overcast feeling of the shot.</td>', 'Appears way too underexposed, but I like the overcast feeling of the shot.', '2003-03-11 20:04:23.000000', NULL, 1),
(235420, 13625, 2000, '<td valign="top">If not for the High-tension lines in the background, I''d think those were toy trains.  Very nice shot.</td>', 'If not for the High-tension lines in the background, I''d think those were toy trains.  Very nice shot.', '2003-03-11 20:05:57.000000', NULL, 1),
(235421, 13963, 6328, '<td valign="top">I think your frame is too large for your photo, but that''s only my thought here.  If anything, the rocks would count as a dam, not a bridge, wouldn''t it?  Nice color on the shores and background with the snow and bushes, I like the reflections in the water too.  Nice photo, but a bridge?</td>', 'I think your frame is too large for your photo, but that''s only my thought here.  If anything, the rocks would count as a dam, not a bridge, wouldn''t it?  Nice color on the shores and background with the snow and bushes, I like the reflections in the water too.  Nice photo, but a bridge?', '2003-03-11 20:06:03.000000', NULL, 1),
(235423, 13641, 5822, '<td valign="top">hahaha...very creative and I like alot...guess this could have also been titled: Nose Bridge.</td>', 'hahaha...very creative and I like alot...guess this could have also been titled: Nose Bridge.', '2003-03-11 20:07:53.000000', NULL, 1),
(235424, 13762, 6328, '<td valign="top">Nice. . .  you can just feel the strength in all that concrete, and the blue sky gives it even more input</td>', 'Nice. . .  you can just feel the strength in all that concrete, and the blue sky gives it even more input', '2003-03-11 20:08:17.000000', NULL, 1),
(235425, 13592, 5822, '<td valign="top">Very well done...excellent focus and I like the peaceful feeling you captured.</td>', 'Very well done...excellent focus and I like the peaceful feeling you captured.', '2003-03-11 20:09:48.000000', NULL, 1),
(235426, 13911, 6328, '<td valign="top">nice shot of the construction of this bridge.  I would like to have seen you back off a bit and show a bit more of the bridge under construction with more of the crane and the bridge, but that''s just me talking.  You show a lot of strength and materials that go into the making of a piece of this bridge.  Nice sharp image against a nice blue sky, and the whole crane is in focus too, kind of hard to do.<br/>Good job.</td>', 'nice shot of the construction of this bridge.  I would like to have seen you back off a bit and show a bit more of the bridge under construction with more of the crane and the bridge, but that''s just me talking.  You show a lot of strength and materials that go into the making of a piece of this bridge.  Nice sharp image against a nice blue sky, and the whole crane is in focus too, kind of hard to do.Good job.', '2003-03-11 20:11:03.000000', NULL, 1),
(235427, 13816, 6328, '<td valign="top">Really nice photo on such an overcast day and rough waters.  You''ve done a good job of catching the storminess of the clouds/weather.</td>', 'Really nice photo on such an overcast day and rough waters.  You''ve done a good job of catching the storminess of the clouds/weather.', '2003-03-11 20:12:55.000000', NULL, 1),
(235428, 13818, 6328, '<td valign="top">You''ve done a great job of capturing the water rushing down below the foot-bridge.  The colour of the bridge is great as is the colour of the various rocks in the water.</td>', 'You''ve done a great job of capturing the water rushing down below the foot-bridge.  The colour of the bridge is great as is the colour of the various rocks in the water.', '2003-03-11 20:15:52.000000', NULL, 1),
(235429, 13825, 6328, '<td valign="top">Nice winter scene with the bridge in the background.  Methinks perhaps you''re a bit far away from the bridge, and would like to have seen you much closer to the bridge rather than looking at the snow and the tree''s.</td>', 'Nice winter scene with the bridge in the background.  Methinks perhaps you''re a bit far away from the bridge, and would like to have seen you much closer to the bridge rather than looking at the snow and the tree''s.', '2003-03-11 20:17:40.000000', NULL, 1),
(235430, 13816, 2373, '<td valign="top">This would look really cool as a panorama shot without so much water in the forground, The water is a little bit distracting and takes away from the subject of the bridge.</td>', 'This would look really cool as a panorama shot without so much water in the forground, The water is a little bit distracting and takes away from the subject of the bridge.', '2003-03-11 20:18:37.000000', NULL, 1),
(235431, 13777, 4877, '<td valign="top">Nice use of perspective and colour</td>', 'Nice use of perspective and colour', '2003-03-11 20:20:14.000000', NULL, 1),
(235432, 13571, 6328, '<td valign="top">This whole photograph looks so old looking.  Great job.  Is that an electric train coming towards us or is that a tower behind it?  Not really sure.  You''re not showing where the bridge leads to, letting us make up our own minds.  The tones are nice, but the photo looks kind of out of focus, especially the train and the fence and stairs.  Did you use a soft focus on the photo?</td>', 'This whole photograph looks so old looking.  Great job.  Is that an electric train coming towards us or is that a tower behind it?  Not really sure.  You''re not showing where the bridge leads to, letting us make up our own minds.  The tones are nice, but the photo looks kind of out of focus, especially the train and the fence and stairs.  Did you use a soft focus on the photo?', '2003-03-11 20:21:57.000000', NULL, 1),
(235433, 13538, 2373, '<td valign="top">I think if your going to use a border it should help the picture flow more and it should be the same on all for sides. I think a black border would really compliment this shot, otherwise really nice. 8, Kevin</td>', 'I think if your going to use a border it should help the picture flow more and it should be the same on all for sides. I think a black border would really compliment this shot, otherwise really nice. 8, Kevin', '2003-03-11 20:22:24.000000', NULL, 1),
(235434, 13640, 2373, '<td valign="top">Nice action on this one. I really like the dog in the air like that. 8, Kevin</td>', 'Nice action on this one. I really like the dog in the air like that. 8, Kevin', '2003-03-11 20:23:01.000000', NULL, 1),
(235435, 13621, 4877, '<td valign="top">Great use of the river for reflective effect.  One thing I would have experimented with would be a closer view of the bridge from one side of the river so that the bridge fills the frame a bit more.  I find the lights a little overpowering, they take a little away from what you were trying to achieve with the bridge.  I like the star effect in the lights though. Good work!</td>', 'Great use of the river for reflective effect.  One thing I would have experimented with would be a closer view of the bridge from one side of the river so that the bridge fills the frame a bit more.  I find the lights a little overpowering, they take a little away from what you were trying to achieve with the bridge.  I like the star effect in the lights though. Good work!', '2003-03-11 20:23:56.000000', NULL, 1),
(235436, 13763, 6328, '<td valign="top">Nice colour to the bridge, and you''ve captured some nice detail on the wood siding and the beams inside the bridge too.  I like the colourful rocks too, and of course all the colours you see in the bushes, trees, and of course the blue sky too.  Nice job.  Did you give the grass a bit of green tone?</td>', 'Nice colour to the bridge, and you''ve captured some nice detail on the wood siding and the beams inside the bridge too.  I like the colourful rocks too, and of course all the colours you see in the bushes, trees, and of course the blue sky too.  Nice job.  Did you give the grass a bit of green tone?', '2003-03-11 20:24:47.000000', NULL, 1),
(235437, 13547, 4877, '<td valign="top">Good photo of an unusual subject.  Other than the title, I dont see a strong connection with bridges theme of this challenge.  Maybe a little dark in the bottom right hand corner.  Very artistic and creative!  Good luck!</td>', 'Good photo of an unusual subject.  Other than the title, I dont see a strong connection with bridges theme of this challenge.  Maybe a little dark in the bottom right hand corner.  Very artistic and creative!  Good luck!', '2003-03-11 20:25:53.000000', NULL, 1),
(235438, 13947, 6110, '<td valign="top">Great job on the exposure, nicely detailed.</td>', 'Great job on the exposure, nicely detailed.', '2003-03-11 20:27:00.000000', NULL, 1),
(235439, 13745, 6328, '<td valign="top">Looks like something out of South America.  What a beauty.  The colour in the trees and bushes are great.  Just look at the colour in those wooden beams, the rust on the steel rails, the steel plates holding beam onto beam with the bolts.  You''ve done a good job here.  Hurray for you!  I mean, you''ve even captured the weeds growing between the tracks just in front of that sign!</td>', 'Looks like something out of South America.  What a beauty.  The colour in the trees and bushes are great.  Just look at the colour in those wooden beams, the rust on the steel rails, the steel plates holding beam onto beam with the bolts.  You''ve done a good job here.  Hurray for you!  I mean, you''ve even captured the weeds growing between the tracks just in front of that sign!', '2003-03-11 20:28:25.000000', NULL, 1),
(235440, 13801, 6110, '<td valign="top">nice composition, very eyecatching.</td>', 'nice composition, very eyecatching.', '2003-03-11 20:28:25.000000', NULL, 1),
(235441, 13678, 4877, '<td valign="top">I like the effect of the reflection from water to bridge back to water.  I also like the old bridge next to the dominant subject of your photo.  I like the small touches of green in the shot too.  Looking at this image makes me want to move to the right further to see more of the old bridge and have a few more bright colours in the shot.  Maybe the bridge you are standing under is a little too dominant.  Keep up the great work!</td>', 'I like the effect of the reflection from water to bridge back to water.  I also like the old bridge next to the dominant subject of your photo.  I like the small touches of green in the shot too.  Looking at this image makes me want to move to the right further to see more of the old bridge and have a few more bright colours in the shot.  Maybe the bridge you are standing under is a little too dominant.  Keep up the great work!', '2003-03-11 20:28:56.000000', NULL, 1),
(235442, 13799, 4877, '<td valign="top">Picturesque for sure!  I like the mood you set in this photo.  Great match between the bridge style and the statue in the background.  Only 2 things I would change about your shot if it were me.  1) take a few steps to the right so the statue is centered between the end of the bridge and the tree to the left.  That would give the photo slightly more balance 2) keep an eye on the image compression, the shot is extremely well thought out, but looses some impact by being pixelated.  Keep up the great work!</td>', 'Picturesque for sure!  I like the mood you set in this photo.  Great match between the bridge style and the statue in the background.  Only 2 things I would change about your shot if it were me.  1) take a few steps to the right so the statue is centered between the end of the bridge and the tree to the left.  That would give the photo slightly more balance 2) keep an eye on the image compression, the shot is extremely well thought out, but looses some impact by being pixelated.  Keep up the great work!', '2003-03-11 20:33:16.000000', NULL, 1),
(235443, 13609, 4585, '<td valign="top">I love this image!  It leans a bit to the left...tiny bit....but this is really good!  GL!</td>', 'I love this image!  It leans a bit to the left...tiny bit....but this is really good!  GL!', '2003-03-11 20:35:44.000000', NULL, 1),
(235444, 13690, 4877, '<td valign="top">Wow!  You''ve certainly captured the moment!  This photo makes me want to zoom and and see more detail.  It has the effect of making me curious which is hopefully what you intended.  I think the sepia style tones are perfect for the subject of the photo.  I would love to see a little more detail in the shot, and maybe a little less haze.  Very emotive!  Keep up the great work!</td>', 'Wow!  You''ve certainly captured the moment!  This photo makes me want to zoom and and see more detail.  It has the effect of making me curious which is hopefully what you intended.  I think the sepia style tones are perfect for the subject of the photo.  I would love to see a little more detail in the shot, and maybe a little less haze.  Very emotive!  Keep up the great work!', '2003-03-11 20:37:28.000000', NULL, 1),
(235447, 13609, 4877, '<td valign="top">Nice shot!  Fantastic detail and depth to the photo.  Good use of tones to create the mood.  Leading lines of the tracks pull you deep into the shot.  Maybe a little too complicated at the top of the shot.  Maybe experiment with a lower perspective which adds more of the tracks to the bottom of the image and leaves less complicated aspects of the subject at the top, that way the tracks end up a the bottom third of the image, as opposed to the top of the bridge structure ending at the bottom third (rule of thirds).  I think this might lessen the impact of the complexity at the top.  But I really think you have a great shot there!  Keep up the great work!</td>', 'Nice shot!  Fantastic detail and depth to the photo.  Good use of tones to create the mood.  Leading lines of the tracks pull you deep into the shot.  Maybe a little too complicated at the top of the shot.  Maybe experiment with a lower perspective which adds more of the tracks to the bottom of the image and leaves less complicated aspects of the subject at the top, that way the tracks end up a the bottom third of the image, as opposed to the top of the bridge structure ending at the bottom third (rule of thirds).  I think this might lessen the impact of the complexity at the top.  But I really think you have a great shot there!  Keep up the great work!', '2003-03-11 20:43:04.000000', NULL, 1),
(235450, 13528, 2352, '<td valign="top">A little better focus would help, but nice shot for the challenge. I like your composition and exposure. It is a beautiful shot and looks like a nice day there<br/>!  -Clicker-</td>', 'A little better focus would help, but nice shot for the challenge. I like your composition and exposure. It is a beautiful shot and looks like a nice day there!  -Clicker-', '2003-03-11 20:46:00.000000', NULL, 1),
(235451, 13939, 4529, '<td valign="top">The weed is much to distracting IOM. The bridge has wonderful character.</td>', 'The weed is much to distracting IOM. The bridge has wonderful character.', '2003-03-11 20:49:32.000000', NULL, 1),
(235452, 13864, 2352, '<td valign="top">I think I see what you are doing with the front section of this pic, but it distracts from the bridge itself. There are beautiful colors on the bridge and in the city. I wonder if that would have been a better shot and eliminate the "story" told in the forground that does add to the shot in one way, but distracts from it in another way in our challenge for the week. This is a well done shot though. I love the feel that the forground gives compared to the lights and glamore of the city -Clciker-</td>', 'I think I see what you are doing with the front section of this pic, but it distracts from the bridge itself. There are beautiful colors on the bridge and in the city. I wonder if that would have been a better shot and eliminate the "story" told in the forground that does add to the shot in one way, but distracts from it in another way in our challenge for the week. This is a well done shot though. I love the feel that the forground gives compared to the lights and glamore of the city -Clciker-', '2003-03-11 20:53:45.000000', NULL, 1),
(235453, 13615, 4529, '<td valign="top">I would like to have seen it a little darker to bring out the detail. Wonderful shot though.</td>', 'I would like to have seen it a little darker to bring out the detail. Wonderful shot though.', '2003-03-11 20:54:15.000000', NULL, 1),
(235455, 13683, 4529, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2003-03-11 20:55:48.000000', NULL, 1),
(235457, 13564, 6007, '<td valign="top">Love it love it, the reflections of the skyline breathtaking.</td>', 'Love it love it, the reflections of the skyline breathtaking.', '2003-03-11 20:59:54.000000', NULL, 1),
(235458, 13706, 6110, '<td valign="top">nice perspective.  seems a little soft though</td>', 'nice perspective.  seems a little soft though', '2003-03-11 21:00:23.000000', NULL, 1),
(235459, 13746, 2352, '<td valign="top">Very well done! Nice composition,focus and exposure. It says something!<br/>I will be curious to find where this was taken. Great shot and good luck!  -Clicker-</td>', 'Very well done! Nice composition,focus and exposure. It says something!I will be curious to find where this was taken. Great shot and good luck!  -Clicker-', '2003-03-11 21:00:31.000000', NULL, 1),
(235461, 13680, 6110, '<td valign="top">reflections are distracting</td>', 'reflections are distracting', '2003-03-11 21:01:24.000000', NULL, 1),
(235462, 13824, 6110, '<td valign="top">nice sharp photo, good composition</td>', 'nice sharp photo, good composition', '2003-03-11 21:02:01.000000', NULL, 1),
(235463, 13960, 6110, '<td valign="top">very cool effect</td>', 'very cool effect', '2003-03-11 21:02:35.000000', NULL, 1),
(235464, 13544, 4877, '<td valign="top">I like the impact your image creates.  The composition is great, in that it creates a road-block effect for the eyes, when looking at the image.  It backs up the sign completely.  If that is what you set out to achieve, youve done well!  I like the dull sepia style tones you have used as well.  Great mood.  Nothing stands out as being technically wrong either.  Great shot!</td>', 'I like the impact your image creates.  The composition is great, in that it creates a road-block effect for the eyes, when looking at the image.  It backs up the sign completely.  If that is what you set out to achieve, youve done well!  I like the dull sepia style tones you have used as well.  Great mood.  Nothing stands out as being technically wrong either.  Great shot!', '2003-03-11 21:02:39.000000', NULL, 1),
(235465, 13794, 6740, '<td valign="top">Very nice photo. Hope no one insults you with a 1 vote.<br/>Would not be surprised to see you take 1st place. 9</td>', 'Very nice photo. Hope no one insults you with a 1 vote.Would not be surprised to see you take 1st place. 9', '2003-03-11 21:03:03.000000', NULL, 1),
(235467, 13903, 6007, '<td valign="top">I have taken hundreds of photos of this bridge. It is hard to catch a good shot with the weather. Bravo, you did a great job. One of my favorites...</td>', 'I have taken hundreds of photos of this bridge. It is hard to catch a good shot with the weather. Bravo, you did a great job. One of my favorites...', '2003-03-11 21:03:21.000000', NULL, 1),
(235468, 13597, 6007, '<td valign="top">The weather made the shot Good job</td>', 'The weather made the shot Good job', '2003-03-11 21:03:57.000000', NULL, 1),
(235469, 13636, 6740, '<td valign="top">Love your angle shot and design. Would not change a thing.</td>', 'Love your angle shot and design. Would not change a thing.', '2003-03-11 21:04:22.000000', NULL, 1),
(235470, 13589, 2352, '<td valign="top">Great composition and execution. Love the focus and color. The bridge really dominates the charactor of the shot and the lake and mountains draw the eye into the shot to give even more. Congratulations and good luck!   -Clicker-</td>', 'Great composition and execution. Love the focus and color. The bridge really dominates the charactor of the shot and the lake and mountains draw the eye into the shot to give even more. Congratulations and good luck!   -Clicker-', '2003-03-11 21:04:27.000000', NULL, 1),
(235471, 13797, 6007, '<td valign="top">People are a bit of a distraction, but the shot makes up for it, Good job, good eye</td>', 'People are a bit of a distraction, but the shot makes up for it, Good job, good eye', '2003-03-11 21:04:28.000000', NULL, 1),
(235472, 13763, 6740, '<td valign="top">Very impressive. Good luck in the contest.</td>', 'Very impressive. Good luck in the contest.', '2003-03-11 21:05:29.000000', NULL, 1),
(235473, 13940, 4877, '<td valign="top">Nice overall effect!  I like the colours, the cloudy background and the bridge itself.  Very nice mood setting image and composed pretty well.  I would watch the angle of the camera, as it seems slightly tilted to the left maybe (unless the bridge itself is slightly skewed)?  Shame about the powerline in the top left.  I like it!  Well done!</td>', 'Nice overall effect!  I like the colours, the cloudy background and the bridge itself.  Very nice mood setting image and composed pretty well.  I would watch the angle of the camera, as it seems slightly tilted to the left maybe (unless the bridge itself is slightly skewed)?  Shame about the powerline in the top left.  I like it!  Well done!', '2003-03-11 21:05:47.000000', NULL, 1),
(235474, 13574, 6007, '<td valign="top">Overall good composition. You have the action fo the wildlife and movement in the flags, good job</td>', 'Overall good composition. You have the action fo the wildlife and movement in the flags, good job', '2003-03-11 21:06:02.000000', NULL, 1),
(235475, 13772, 6740, '<td valign="top">I would not change a thing. Very beautiful photo.</td>', 'I would not change a thing. Very beautiful photo.', '2003-03-11 21:07:05.000000', NULL, 1),
(235476, 13794, 6007, '<td valign="top">Great shot. One of my favorites. I am one for reflections, lighting, mood. You captured all of those=)</td>', 'Great shot. One of my favorites. I am one for reflections, lighting, mood. You captured all of those=)', '2003-03-11 21:07:06.000000', NULL, 1),
(235477, 13824, 6007, '<td valign="top">I can see this picture on an antique item. It evokes a feeling. Good job</td>', 'I can see this picture on an antique item. It evokes a feeling. Good job', '2003-03-11 21:07:50.000000', NULL, 1),
(235478, 13824, 6328, '<td valign="top">Lovely b&amp;W photo.  You''ve got nice tones showing, good crisp focus, nice shadows.  Is that a railroad below the bridge? Or a road?  Realy nice photograph.</td>', 'Lovely b&W photo.  You''ve got nice tones showing, good crisp focus, nice shadows.  Is that a railroad below the bridge? Or a road?  Realy nice photograph.', '2003-03-11 21:07:59.000000', NULL, 1),
(235479, 13804, 4877, '<td valign="top">First impressions are elengant and old-world.  I think your colour tones are great for this image.  Maybe the trees distract a little in the foreground, but that does not detract from the mood and impact of the image detrimentally.  Well done!</td>', 'First impressions are elengant and old-world.  I think your colour tones are great for this image.  Maybe the trees distract a little in the foreground, but that does not detract from the mood and impact of the image detrimentally.  Well done!', '2003-03-11 21:08:03.000000', NULL, 1),
(235480, 13652, 6007, '<td valign="top">Complex it is indeed</td>', 'Complex it is indeed', '2003-03-11 21:08:18.000000', NULL, 1),
(235481, 13963, 6740, '<td valign="top">Love the colors and reflections. I hope no one insults you with a 1 vote.</td>', 'Love the colors and reflections. I hope no one insults you with a 1 vote.', '2003-03-11 21:08:25.000000', NULL, 1),
(235482, 13772, 6007, '<td valign="top">Put it on a postcard, good eye</td>', 'Put it on a postcard, good eye', '2003-03-11 21:08:37.000000', NULL, 1),
(235483, 13648, 6007, '<td valign="top">a bit blurry but good contrast</td>', 'a bit blurry but good contrast', '2003-03-11 21:09:28.000000', NULL, 1),
(235484, 13565, 2352, '<td valign="top">Well, I knew this shot would be in there and you took a beauty. (I lived in S.F. for three years) Your focus is sharp, the composition is well done, and the colors are beautiful. Congratulation and good luck!  -Clicker-</td>', 'Well, I knew this shot would be in there and you took a beauty. (I lived in S.F. for three years) Your focus is sharp, the composition is well done, and the colors are beautiful. Congratulation and good luck!  -Clicker-', '2003-03-11 21:09:37.000000', NULL, 1),
(235485, 13936, 6328, '<td valign="top">Don''t really see anything artistic here.  See the reflections of the sun on the underbelly of the bridge, but the garbage in the water takes away from it all.</td>', 'Don''t really see anything artistic here.  See the reflections of the sun on the underbelly of the bridge, but the garbage in the water takes away from it all.', '2003-03-11 21:09:37.000000', NULL, 1),
(235486, 13955, 4877, '<td valign="top">Beautiful use of curves and silhouettes.  The red graffiti adds some interest to the shot, although I think personally it would have been great to use B&amp;W or sepia to reduce this impact on the mood you have created.  Great bridge specimen!  Well done!</td>', 'Beautiful use of curves and silhouettes.  The red graffiti adds some interest to the shot, although I think personally it would have been great to use B&W or sepia to reduce this impact on the mood you have created.  Great bridge specimen!  Well done!', '2003-03-11 21:10:30.000000', NULL, 1),
(235488, 13912, 6328, '<td valign="top">Lovely photograph.  You''ve captured it just at the right moment of evening, sun going down, creating that golden colour on the bridge, especially on the middle piece.  I like the way you''ve captured the lights coming on at first night, the evening sun glistening off the water. . .  Great photography.</td>', 'Lovely photograph.  You''ve captured it just at the right moment of evening, sun going down, creating that golden colour on the bridge, especially on the middle piece.  I like the way you''ve captured the lights coming on at first night, the evening sun glistening off the water. . .  Great photography.', '2003-03-11 21:11:39.000000', NULL, 1),
(235489, 13562, 4877, '<td valign="top">First impression is "busy" which fits with your title.  Well done!  The angle of the camera seems to be slightly tilting to the right, or is that just me?  The bridge coming from the left feels a little close to the point of origin of the shot.  Maybe a vantage point a few steps to the right might have changed that (depending on how practical that was).  Overall, I like it!</td>', 'First impression is "busy" which fits with your title.  Well done!  The angle of the camera seems to be slightly tilting to the right, or is that just me?  The bridge coming from the left feels a little close to the point of origin of the shot.  Maybe a vantage point a few steps to the right might have changed that (depending on how practical that was).  Overall, I like it!', '2003-03-11 21:13:23.000000', NULL, 1),
(235490, 13880, 6328, '<td valign="top">You''ve captured a nice atmosphere here.  The swirling water with the slow shutter speed works well.  The colors in the bridge show up nicely, and the tree bark colors are also nice along with the nice green moss on the rocks and ground.  Good job.</td>', 'You''ve captured a nice atmosphere here.  The swirling water with the slow shutter speed works well.  The colors in the bridge show up nicely, and the tree bark colors are also nice along with the nice green moss on the rocks and ground.  Good job.', '2003-03-11 21:14:01.000000', NULL, 1),
(235491, 13975, 6480, '<td valign="top">nice colors, nice angle</td>', 'nice colors, nice angle', '2003-03-11 21:14:19.000000', NULL, 1),
(235493, 13954, 6480, '<td valign="top">too close up, you can''t really tell what the picture is..nice clarity though</td>', 'too close up, you can''t really tell what the picture is..nice clarity though', '2003-03-11 21:15:30.000000', NULL, 1),
(235494, 13562, 6328, '<td valign="top">Whoa.   Do you get lost very often?  Great shot of tiered bridges, ramps, whatever you want to call it - - it looks great!</td>', 'Whoa.   Do you get lost very often?  Great shot of tiered bridges, ramps, whatever you want to call it - - it looks great!', '2003-03-11 21:15:44.000000', NULL, 1),
(235495, 13677, 6480, '<td valign="top">nice angle, a little dark though</td>', 'nice angle, a little dark though', '2003-03-11 21:16:00.000000', NULL, 1),
