(235804, 13652, 6172, '<td valign="top">Oh, wow, did you have to sneak around to get this shot?  Nice approach, great colors and all.</td>', 'Oh, wow, did you have to sneak around to get this shot?  Nice approach, great colors and all.', '2003-03-12 02:25:51.000000', NULL, 1),
(235805, 13903, 6172, '<td valign="top">Oh come on, you stole this from a magazine, didn''t you? : )</td>', 'Oh come on, you stole this from a magazine, didn''t you? : )', '2003-03-12 02:27:02.000000', NULL, 1),
(235807, 13818, 6172, '<td valign="top">Very nice job with the water.</td>', 'Very nice job with the water.', '2003-03-12 02:27:51.000000', NULL, 1),
(235808, 13746, 6172, '<td valign="top">Very nice shot, I see this is in the tropics, right?  The Philippines?  Good luck!</td>', 'Very nice shot, I see this is in the tropics, right?  The Philippines?  Good luck!', '2003-03-12 02:28:47.000000', NULL, 1),
(235809, 13762, 6172, '<td valign="top">I don''t like your title, but I sure do like your photo!  Nice colors and perspective.</td>', 'I don''t like your title, but I sure do like your photo!  Nice colors and perspective.', '2003-03-12 02:29:55.000000', NULL, 1),
(235810, 13737, 6172, '<td valign="top">Beautiful colors!  Japan?  The stalks in the foreground do detract a little from the shot.</td>', 'Beautiful colors!  Japan?  The stalks in the foreground do detract a little from the shot.', '2003-03-12 02:32:02.000000', NULL, 1),
(235811, 13583, 6172, '<td valign="top">This is not very good, it looks like a snap-shot, and not a very good one at that.</td>', 'This is not very good, it looks like a snap-shot, and not a very good one at that.', '2003-03-12 02:33:58.000000', NULL, 1),
(235813, 13723, 6172, '<td valign="top">You should take advantage of our allowance for a bigger size!</td>', 'You should take advantage of our allowance for a bigger size!', '2003-03-12 02:36:00.000000', NULL, 1),
(235814, 13609, 6172, '<td valign="top">I like it!  Wonderful texture, and a good angle on a shot that would have been otherwise boring.  Interesting color choice.</td>', 'I like it!  Wonderful texture, and a good angle on a shot that would have been otherwise boring.  Interesting color choice.', '2003-03-12 02:39:06.000000', NULL, 1),
(235815, 13940, 6172, '<td valign="top">Not very good lighting here.</td>', 'Not very good lighting here.', '2003-03-12 02:39:28.000000', NULL, 1),
(235816, 13803, 6172, '<td valign="top">Too much empty space, I think.</td>', 'Too much empty space, I think.', '2003-03-12 02:43:35.000000', NULL, 1),
(235818, 13764, 4877, '<td valign="top">Really nice shot!  Excellent atmosphere created and fantastic subject matter.  Well done, and good luck!</td>', 'Really nice shot!  Excellent atmosphere created and fantastic subject matter.  Well done, and good luck!', '2003-03-12 02:48:37.000000', NULL, 1),
(235819, 13721, 5728, '<td valign="top">I thought I''d see a lot more garden bridges in this challenge but there really weren''t that many. I like this one very much, the bridge isn''t just a straight out bridge but has a lot of charachter to it with those bends in the middle.</td>', 'I thought I''d see a lot more garden bridges in this challenge but there really weren''t that many. I like this one very much, the bridge isn''t just a straight out bridge but has a lot of charachter to it with those bends in the middle.', '2003-03-12 02:49:04.000000', NULL, 1),
(235820, 13675, 4877, '<td valign="top">Fantastic photo!  Captures the essence of the location perfectly!  Good luck!</td>', 'Fantastic photo!  Captures the essence of the location perfectly!  Good luck!', '2003-03-12 02:49:52.000000', NULL, 1),
(235821, 13745, 6172, '<td valign="top">Someone else had a picture of this same bridge?  Looks like it.  Nice shot though!</td>', 'Someone else had a picture of this same bridge?  Looks like it.  Nice shot though!', '2003-03-12 02:51:35.000000', NULL, 1),
(235822, 13796, 4877, '<td valign="top">What a great idea!  Amazing results, and the image composition is fantastic!  Good luck!</td>', 'What a great idea!  Amazing results, and the image composition is fantastic!  Good luck!', '2003-03-12 02:51:52.000000', NULL, 1),
(235823, 13541, 6172, '<td valign="top">Seems like it might have been a better shot from closer to the bridge?</td>', 'Seems like it might have been a better shot from closer to the bridge?', '2003-03-12 02:53:22.000000', NULL, 1),
(235824, 13594, 4877, '<td valign="top">I really like this shot!  You have composed it extremely well, drawing the eyes to the bridge by border-framing with the foreground branches.  Background has enough interest to build on the subject without detracting from it.  Really well thought out photo!  Well done!</td>', 'I really like this shot!  You have composed it extremely well, drawing the eyes to the bridge by border-framing with the foreground branches.  Background has enough interest to build on the subject without detracting from it.  Really well thought out photo!  Well done!', '2003-03-12 02:54:00.000000', NULL, 1),
(235827, 13977, 4877, '<td valign="top">Beautiful shot! Very well balanced!</td>', 'Beautiful shot! Very well balanced!', '2003-03-12 02:59:14.000000', NULL, 1),
(235828, 13564, 4877, '<td valign="top">Amazing effect with a Fish-eye lense!  Wouldnt have thought of this myself (doesnt help that I dont have a Fish-eye lense either!).  Unique!</td>', 'Amazing effect with a Fish-eye lense!  Wouldnt have thought of this myself (doesnt help that I dont have a Fish-eye lense either!).  Unique!', '2003-03-12 03:00:37.000000', NULL, 1),
(235839, 13753, 4877, '<td valign="top">Great shot of the Harbour Bridge!  Really like the detail you have captured and the clouds in the background add to the mood.  Well done!</td>', 'Great shot of the Harbour Bridge!  Really like the detail you have captured and the clouds in the background add to the mood.  Well done!', '2003-03-12 03:33:25.000000', NULL, 1),
(235840, 13794, 1717, '<td valign="top">oh my!!  this is beautiful!!  i love the colors and how the bridge leads to the cathedral.  gorgeous!!!  10 from me</td>', 'oh my!!  this is beautiful!!  i love the colors and how the bridge leads to the cathedral.  gorgeous!!!  10 from me', '2003-03-12 03:39:07.000000', NULL, 1),
(235842, 13721, 4767, '<td valign="top">A little too much foreground, perhaps.  Nice photo, though.</td>', 'A little too much foreground, perhaps.  Nice photo, though.', '2003-03-12 03:47:00.000000', NULL, 1),
(235855, 13836, 4388, '<td valign="top">great image, I would like to have seen the image rotated some.</td>', 'great image, I would like to have seen the image rotated some.', '2003-03-12 06:48:05.000000', NULL, 1),
(235856, 13674, 4388, '<td valign="top">nice shot, would like to have seen the colors saturated a little more.</td>', 'nice shot, would like to have seen the colors saturated a little more.', '2003-03-12 06:48:48.000000', NULL, 1),
(235859, 13678, 6110, '<td valign="top">Excellent composition, good work with tough lighting</td>', 'Excellent composition, good work with tough lighting', '2003-03-12 07:23:20.000000', NULL, 1),
(235860, 13603, 6110, '<td valign="top">spectacular scene</td>', 'spectacular scene', '2003-03-12 07:28:24.000000', NULL, 1),
(235862, 13783, 6110, '<td valign="top">Nice clean, bold composition.  Maybe crop in from left to eliminate that small background area?</td>', 'Nice clean, bold composition.  Maybe crop in from left to eliminate that small background area?', '2003-03-12 07:30:22.000000', NULL, 1),
(235863, 13531, 6110, '<td valign="top">Nice perspective, great detail</td>', 'Nice perspective, great detail', '2003-03-12 07:32:03.000000', NULL, 1),
(235868, 13976, 7010, '<td valign="top">Nice shot! My only comment is that the lines are leading out of the frame. That makes this picture have a ''unconfortable feel''. Regards, Marco.</td>', 'Nice shot! My only comment is that the lines are leading out of the frame. That makes this picture have a ''unconfortable feel''. Regards, Marco.', '2003-03-12 07:42:08.000000', NULL, 1),
(235870, 13948, 6458, '<td valign="top">I really like the composition of this photo. On one hand you have the tree running down the vertical middle, and on the other you have the bridge support on the left vertical third then relative emptiness on the right third. The bridge deck rests just about on the top horizontal third and the pillar enters the water on the bottom third. The openness/emptiness on the right side just plain works for me. Good job!</td>', 'I really like the composition of this photo. On one hand you have the tree running down the vertical middle, and on the other you have the bridge support on the left vertical third then relative emptiness on the right third. The bridge deck rests just about on the top horizontal third and the pillar enters the water on the bottom third. The openness/emptiness on the right side just plain works for me. Good job!', '2003-03-12 07:46:56.000000', NULL, 1),
(235873, 13701, 5865, '<td valign="top">I really loved this image.  The shape of the bridges supports are interesting and the line of the railings leads the eye into the shot.  I also like the colour combination of the brickwork and iron railings.  If I have one criticism, the depth of field looks wrong to me, with the near part of the bridge out of focus.  Nevertheless, I liked it.</td>', 'I really loved this image.  The shape of the bridges supports are interesting and the line of the railings leads the eye into the shot.  I also like the colour combination of the brickwork and iron railings.  If I have one criticism, the depth of field looks wrong to me, with the near part of the bridge out of focus.  Nevertheless, I liked it.', '2003-03-12 07:57:20.000000', NULL, 1),
(235875, 13818, 5865, '<td valign="top">Very nice composition and I always like seeing the movement of water.</td>', 'Very nice composition and I always like seeing the movement of water.', '2003-03-12 07:57:53.000000', NULL, 1),
(235876, 13844, 5865, '<td valign="top">I like the composition of this shot.  The tree adds good shape to the image and is positioned nicely on the third.  I feel, however, that the buildings, cars and wire fence detract from the shot.</td>', 'I like the composition of this shot.  The tree adds good shape to the image and is positioned nicely on the third.  I feel, however, that the buildings, cars and wire fence detract from the shot.', '2003-03-12 07:59:46.000000', NULL, 1),
(235877, 13783, 5865, '<td valign="top">Lovely shape in this image and a nice composition generally.</td>', 'Lovely shape in this image and a nice composition generally.', '2003-03-12 08:00:46.000000', NULL, 1),
(235878, 13609, 5865, '<td valign="top">A very unusual structure that adds interesting shpe to the shot.  I also like the colour.  Generally, a well-composed photograph.</td>', 'A very unusual structure that adds interesting shpe to the shot.  I also like the colour.  Generally, a well-composed photograph.', '2003-03-12 08:02:05.000000', NULL, 1),
(235879, 13650, 5865, '<td valign="top">Lovely bridge. Nice colour and the shape of the arches makes a good composition.  I think it is unfortunate that the shadow leaves some of the bridge in darkness.</td>', 'Lovely bridge. Nice colour and the shape of the arches makes a good composition.  I think it is unfortunate that the shadow leaves some of the bridge in darkness.', '2003-03-12 08:03:35.000000', NULL, 1),
(235880, 13719, 5865, '<td valign="top">A nice composition with the trees and bushes providing a frame for the bridge.  The only problem I have is that it makes me feel too cold :)</td>', 'A nice composition with the trees and bushes providing a frame for the bridge.  The only problem I have is that it makes me feel too cold :)', '2003-03-12 08:05:06.000000', NULL, 1),
(235881, 13768, 5865, '<td valign="top">A very novel idea, but the focus seems a bit off.  I would have liked to have seen a sharper photograph.</td>', 'A very novel idea, but the focus seems a bit off.  I would have liked to have seen a sharper photograph.', '2003-03-12 08:06:10.000000', NULL, 1),
(235882, 13671, 5865, '<td valign="top">I like the abstract look to the shot.  It makes for a good design.</td>', 'I like the abstract look to the shot.  It makes for a good design.', '2003-03-12 08:07:20.000000', NULL, 1),
(235883, 13729, 5865, '<td valign="top">I don''t think that this is a well-composed shot.  I think it would look better if you cropped some of the bottom of the photograph.</td>', 'I don''t think that this is a well-composed shot.  I think it would look better if you cropped some of the bottom of the photograph.', '2003-03-12 08:08:15.000000', NULL, 1),
(235884, 13876, 5865, '<td valign="top">Absolutely fantastic composition.  I love it.  The shape and colour that has been added by the bridge in the foreground makes this a powerful image for me.</td>', 'Absolutely fantastic composition.  I love it.  The shape and colour that has been added by the bridge in the foreground makes this a powerful image for me.', '2003-03-12 08:09:18.000000', NULL, 1),
(235885, 13573, 5865, '<td valign="top">A lovely scene, but the electricity pilons detract from the image.</td>', 'A lovely scene, but the electricity pilons detract from the image.', '2003-03-12 08:09:50.000000', NULL, 1),
(235887, 13688, 1570, '<td valign="top">this is so-o-o-o pretty! no criticism here... 10.</td>', 'this is so-o-o-o pretty! no criticism here... 10.', '2003-03-12 08:33:20.000000', NULL, 1),
(235892, 13794, 1570, '<td valign="top">beautiful, just beautiful, no criticism here! 10.</td>', 'beautiful, just beautiful, no criticism here! 10.', '2003-03-12 08:51:39.000000', NULL, 1),
(235893, 13573, 1570, '<td valign="top">that''s a great picture, can''t offer any criticism! love it.</td>', 'that''s a great picture, can''t offer any criticism! love it.', '2003-03-12 08:53:39.000000', NULL, 1),
(235896, 13803, 1570, '<td valign="top">nice curves... i like the composition, but the sky is a little noisy...one of the bridges is pixelated on the bottom, too.</td>', 'nice curves... i like the composition, but the sky is a little noisy...one of the bridges is pixelated on the bottom, too.', '2003-03-12 09:05:46.000000', NULL, 1),
(235906, 13735, 1570, '<td valign="top">or "what not to do...."</td>', 'or "what not to do...."', '2003-03-12 09:19:40.000000', NULL, 1),
(235907, 13861, 1570, '<td valign="top">very dynamic and clear picture, great job!</td>', 'very dynamic and clear picture, great job!', '2003-03-12 09:21:48.000000', NULL, 1),
(235913, 13765, 1570, '<td valign="top">nice and clear picture... i would crop about an inch from the topto get rid of some branches and bring the eye to the main subject of the photo.</td>', 'nice and clear picture... i would crop about an inch from the topto get rid of some branches and bring the eye to the main subject of the photo.', '2003-03-12 09:36:37.000000', NULL, 1),
(235921, 13565, 1280, '<td valign="top">Beautiful job!</td>', 'Beautiful job!', '2003-03-12 10:16:28.000000', NULL, 1),
(235923, 13636, 1280, '<td valign="top">Nice perspective, well exposed.  Good work!</td>', 'Nice perspective, well exposed.  Good work!', '2003-03-12 10:17:42.000000', NULL, 1),
(235926, 13751, 1280, '<td valign="top">Very nice, old world feel.  Good choice of color for this.</td>', 'Very nice, old world feel.  Good choice of color for this.', '2003-03-12 10:23:06.000000', NULL, 1),
(235928, 13960, 1280, '<td valign="top">Lovely idea, well executed.</td>', 'Lovely idea, well executed.', '2003-03-12 10:24:19.000000', NULL, 1),
(235931, 13821, 1280, '<td valign="top">Wow!  This one is different!  I get a real sense of "place" here and there is a lot of character.  Very nice and interesting!</td>', 'Wow!  This one is different!  I get a real sense of "place" here and there is a lot of character.  Very nice and interesting!', '2003-03-12 10:26:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(235936, 13657, 1280, '<td valign="top">Soooooooo interesting.  Nice lighting!</td>', 'Soooooooo interesting.  Nice lighting!', '2003-03-12 10:31:18.000000', NULL, 1),
