(235957, 13768, 1360, '<td valign="top">increased color would really help this photo. Prehaps some extra light might have also helped. 4.</td>', 'increased color would really help this photo. Prehaps some extra light might have also helped. 4.', '2003-03-12 10:52:40.000000', NULL, 1),
(235959, 13852, 1360, '<td valign="top">This picture really pulls at the heartstrings.  Overall, the execution is average, but the emotion it brings really makes up for that.  6.</td>', 'This picture really pulls at the heartstrings.  Overall, the execution is average, but the emotion it brings really makes up for that.  6.', '2003-03-12 10:54:17.000000', NULL, 1),
(235961, 13641, 641, '<td valign="top">Well done, and a great twist to the challenge.</td>', 'Well done, and a great twist to the challenge.', '2003-03-12 10:59:43.000000', NULL, 1),
