(236779, 13565, 6663, '<td valign="top">Classic.....brings back memories....love it</td>', 'Classic.....brings back memories....love it', '2003-03-13 15:21:38.000000', NULL, 1),
(236780, 13575, 6663, '<td valign="top">Good atmosphere, nice and soft for a hard subject.</td>', 'Good atmosphere, nice and soft for a hard subject.', '2003-03-13 15:22:43.000000', NULL, 1),
