(237977, 13751, 554, '<td valign="top">sepia was nice choice here</td>', 'sepia was nice choice here', '2003-03-16 15:45:08.000000', NULL, 1),
(237979, 13674, 554, '<td valign="top">OK, I think you have the idea now. Try one by yourself.<br/>Just kidding.....nice shot.</td>', 'OK, I think you have the idea now. Try one by yourself.Just kidding.....nice shot.', '2003-03-16 15:52:02.000000', NULL, 1),
